/**
 * Artifact Renderer Components
 * ============================
 * Renders different artifact types generated by the AG-UI backend:
 * - Task List (Antigravity-style progress tracking)
 * - Docking Results (binding energy charts)
 * - Interaction Maps (protein-ligand contacts)
 * - Cluster Visualizations (t-SNE scatter plots)
 * - 3D Structures (links to Mol* viewer)
 * - Google Docs-style comments (Antigravity "trust bridge")
 */

import React, { useState, useEffect } from 'react';
import {
  CheckCircle2,
  Circle,
  Loader2,
  ListTodo,
  Activity,
  Dna,
  Server,
  BookOpen,
  MessageCircle,
  Send,
  Check,
  X
} from 'lucide-react';
import {
  Artifact,
  ArtifactType,
  TaskListContent,
  DockingResultContent,
  ProtocolContent,
  ExperimentMatrixContent,
  DiscoveryReportContent,
  PublicationFigureContent,
} from '../services/aguiService';

// =============================================================================
// Task List Artifact (Antigravity-style)
// =============================================================================

interface TaskListProps {
  content: TaskListContent;
}

export const TaskListArtifact: React.FC<TaskListProps> = ({ content }) => {
  const { tasks, completed, total } = content;
  const progress = total > 0 ? (completed / total) * 100 : 0;

  return (
    <div className="bg-am-secondary rounded-lg border border-am-border overflow-hidden">
      {/* Header */}
      <div className="bg-am-tertiary px-4 py-3 border-b border-am-border flex items-center justify-between">
        <h3 className="text-sm font-semibold text-am-text-primary flex items-center gap-2">
          <ListTodo className="w-4 h-4 text-am-accent" />
          Research Protocol
        </h3>
        <div className="flex items-center gap-2">
           <span className="text-xs font-mono text-am-text-muted bg-am-primary px-2 py-0.5 rounded border border-am-border">
             {completed}/{total} Steps
           </span>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="h-1 bg-am-primary w-full">
        <div
          className="h-full bg-am-accent transition-all duration-500 ease-out"
          style={{ width: `${progress}%` }}
        />
      </div>

      {/* Tasks */}
      <div className="divide-y divide-am-border/50">
        {tasks.map((task, idx) => (
          <div
            key={idx}
            className={`px-4 py-3 flex items-start gap-3 transition-colors ${
              task.status === 'in_progress' ? 'bg-am-accent/10' : 'bg-am-secondary'
            }`}
          >
            {/* Icon */}
            <div className="mt-0.5 flex-shrink-0">
              {task.status === 'completed' ? (
                <CheckCircle2 className="w-4 h-4 text-green-400" />
              ) : task.status === 'in_progress' ? (
                <Loader2 className="w-4 h-4 text-am-accent animate-spin" />
              ) : (
                <Circle className="w-4 h-4 text-am-text-muted" />
              )}
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
              <p className={`text-sm font-medium ${
                task.status === 'completed' ? 'text-am-text-muted' :
                task.status === 'in_progress' ? 'text-am-accent' : 'text-am-text-secondary'
              }`}>
                {task.name}
              </p>
              <div className="mt-1 flex items-center gap-2">
                <span className="text-[10px] text-am-text-muted font-mono uppercase tracking-wider">
                  {(task.tool || 'processing').replace(/_/g, ' ')}
                </span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

// =============================================================================
// Docking Results Artifact
// =============================================================================

interface DockingResultProps {
  content: DockingResultContent;
}

export const DockingResultArtifact: React.FC<DockingResultProps> = ({ content }) => {
  const { binding_scores, ensemble_average, visualization } = content;
  const bestScore = Math.min(...binding_scores);
  const worstScore = Math.max(...binding_scores);

  // Determine binding strength
  const getBindingStrength = (score: number) => {
    if (score <= -7) return { label: 'Strong', color: 'text-green-400', bg: 'bg-green-500' };
    if (score <= -5) return { label: 'Moderate', color: 'text-yellow-400', bg: 'bg-yellow-500' };
    return { label: 'Weak', color: 'text-red-400', bg: 'bg-red-500' };
  };

  const strength = getBindingStrength(bestScore);

  return (
    <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-sm font-semibold text-slate-200 flex items-center gap-2">
          <svg className="w-4 h-4 text-purple-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M12 2L2 7l10 5 10-5-10-5z" />
            <path d="M2 17l10 5 10-5" />
            <path d="M2 12l10 5 10-5" />
          </svg>
          Docking Results
        </h3>
        <span className={`text-xs px-2 py-0.5 rounded ${strength.bg} text-black font-medium`}>
          {strength.label} Binding
        </span>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-3 gap-3 mb-4">
        <div className="bg-slate-800/50 rounded-lg p-3 text-center">
          <div className={`text-lg font-bold ${strength.color}`}>
            {bestScore.toFixed(1)}
          </div>
          <div className="text-[10px] text-slate-500 uppercase">Best (kcal/mol)</div>
        </div>
        <div className="bg-slate-800/50 rounded-lg p-3 text-center">
          <div className="text-lg font-bold text-slate-300">
            {ensemble_average?.toFixed(1) || '-'}
          </div>
          <div className="text-[10px] text-slate-500 uppercase">Ensemble Avg</div>
        </div>
        <div className="bg-slate-800/50 rounded-lg p-3 text-center">
          <div className="text-lg font-bold text-slate-400">
            {binding_scores.length}
          </div>
          <div className="text-[10px] text-slate-500 uppercase">Clusters</div>
        </div>
      </div>

      {/* Bar Chart */}
      <div className="space-y-1.5">
        <div className="text-xs text-slate-500 mb-2">Binding Energy per Cluster</div>
        {binding_scores.map((score, idx) => {
          const width = ((score - worstScore) / (bestScore - worstScore)) * 100;
          const barStrength = getBindingStrength(score);

          return (
            <div key={idx} className="flex items-center gap-2">
              <span className="text-[10px] text-slate-500 w-8">C{idx + 1}</span>
              <div className="flex-1 h-4 bg-slate-800 rounded overflow-hidden">
                <div
                  className={`h-full ${barStrength.bg} opacity-80 transition-all duration-500`}
                  style={{ width: `${Math.max(5, width)}%` }}
                />
              </div>
              <span className={`text-xs font-mono w-14 text-right ${barStrength.color}`}>
                {score.toFixed(1)}
              </span>
            </div>
          );
        })}
      </div>

      {/* Threshold Legend */}
      {visualization?.threshold_lines && (
        <div className="mt-4 pt-3 border-t border-slate-800 flex items-center gap-4">
          {visualization.threshold_lines.map((line, idx) => (
            <div key={idx} className="flex items-center gap-1.5 text-[10px]">
              <span
                className="w-2 h-2 rounded"
                style={{ backgroundColor: line.color }}
              />
              <span className="text-slate-500">{line.label}</span>
              <span className="text-slate-400">({line.value})</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// =============================================================================
// Interaction Map Artifact
// =============================================================================

interface InteractionMapContent {
  interactions: {
    residues?: string[];
    h_bonds?: number;
    hydrophobic?: number;
    aromatic?: number;
    ionic?: number;
  };
  visualization: {
    type: string;
    residues: string[];
    interaction_types: string[];
  };
}

interface InteractionMapProps {
  content: InteractionMapContent;
}

export const InteractionMapArtifact: React.FC<InteractionMapProps> = ({ content }) => {
  const { interactions } = content;

  const interactionTypes = [
    { key: 'h_bonds', label: 'H-Bonds', color: 'bg-blue-500', icon: '⚡' },
    { key: 'hydrophobic', label: 'Hydrophobic', color: 'bg-yellow-500', icon: '🔶' },
    { key: 'aromatic', label: 'π-Stacking', color: 'bg-purple-500', icon: '⭕' },
    { key: 'ionic', label: 'Ionic', color: 'bg-red-500', icon: '±' },
  ];

  return (
    <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
      {/* Header */}
      <div className="flex items-center gap-2 mb-4">
        <svg className="w-4 h-4 text-cyan-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
          <circle cx="12" cy="12" r="10" />
          <path d="M12 16v-4" />
          <path d="M12 8h.01" />
        </svg>
        <h3 className="text-sm font-semibold text-slate-200">Interaction Analysis</h3>
      </div>

      {/* Interaction Counts */}
      <div className="grid grid-cols-2 gap-2">
        {interactionTypes.map(type => {
          const count = (interactions as any)[type.key] || 0;
          return (
            <div
              key={type.key}
              className="flex items-center gap-3 p-3 bg-slate-800/50 rounded-lg"
            >
              <div className={`w-8 h-8 ${type.color} rounded-lg flex items-center justify-center text-white text-sm`}>
                {type.icon}
              </div>
              <div>
                <div className="text-lg font-bold text-slate-200">{count}</div>
                <div className="text-[10px] text-slate-500">{type.label}</div>
              </div>
            </div>
          );
        })}
      </div>

      {/* Residues List */}
      {interactions.residues && interactions.residues.length > 0 && (
        <div className="mt-4 pt-3 border-t border-slate-800">
          <div className="text-xs text-slate-500 mb-2">Interacting Residues</div>
          <div className="flex flex-wrap gap-1">
            {interactions.residues.map((res, idx) => (
              <span
                key={idx}
                className="px-2 py-0.5 bg-slate-800 rounded text-xs text-slate-300 font-mono"
              >
                {res}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

