// =============================================================================
// Artifact Feedback Component (Google Docs-style)
// =============================================================================

const API_BASE = 'http://localhost:8002';

interface FeedbackItem {
  id: string;
  user_id: string;
  comment: string;
  resolved: boolean;
  created_at: string;
}

interface ArtifactWithFeedbackProps {
  artifact: Artifact;
  onStructureClick?: (pdbData: string) => void;
  children: React.ReactNode;
}

const ArtifactWithFeedback: React.FC<ArtifactWithFeedbackProps> = ({
  artifact,
  children
}) => {
  const [showComments, setShowComments] = useState(false);
  const [comments, setComments] = useState<FeedbackItem[]>([]);
  const [newComment, setNewComment] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Fetch existing comments
  useEffect(() => {
    const fetchComments = async () => {
      try {
        const response = await fetch(`${API_BASE}/feedback/${artifact.id}`);
        if (response.ok) {
          const data = await response.json();
          setComments(data.feedback || []);
        }
      } catch (e) {
        console.log('Failed to fetch comments:', e);
      }
    };
    if (showComments) {
      fetchComments();
    }
  }, [artifact.id, showComments]);

  const handleAddComment = async () => {
    if (!newComment.trim() || isSubmitting) return;

    setIsSubmitting(true);
    try {
      const response = await fetch(`${API_BASE}/feedback`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          artifact_id: artifact.id,
          comment: newComment.trim()
        })
      });

      if (response.ok) {
        const newFeedback = await response.json();
        setComments(prev => [...prev, newFeedback]);
        setNewComment('');
      }
    } catch (e) {
      console.error('Failed to add comment:', e);
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleResolve = async (feedbackId: string) => {
    try {
      const response = await fetch(`${API_BASE}/feedback/${feedbackId}/resolve`, {
        method: 'PUT'
      });
      if (response.ok) {
        setComments(prev =>
          prev.map(c => c.id === feedbackId ? { ...c, resolved: true } : c)
        );
      }
    } catch (e) {
      console.error('Failed to resolve comment:', e);
    }
  };

  const unresolvedCount = comments.filter(c => !c.resolved).length;

  return (
    <div className="relative">
      {children}

      {/* Comment Button */}
      <div className="absolute top-2 right-2 flex items-center gap-2">
        <button
          onClick={() => setShowComments(!showComments)}
          className={`flex items-center gap-1.5 px-2 py-1 text-xs rounded-lg transition-colors ${
            showComments
              ? 'bg-am-accent text-white'
              : 'bg-am-tertiary text-am-text-secondary hover:bg-am-border'
          }`}
        >
          <MessageCircle className="w-3 h-3" />
          <span>Comments</span>
          {unresolvedCount > 0 && (
            <span className="bg-red-500 text-white text-[10px] px-1.5 rounded-full">
              {unresolvedCount}
            </span>
          )}
        </button>
      </div>

      {/* Comments Panel */}
      {showComments && (
        <div className="mt-3 pt-3 border-t border-am-border space-y-3">
          {/* Existing Comments */}
          {comments.length > 0 && (
            <div className="space-y-2">
              {comments.map(comment => (
                <div
                  key={comment.id}
                  className={`p-2 rounded-lg text-xs ${
                    comment.resolved
                      ? 'bg-am-tertiary/50 opacity-60'
                      : 'bg-am-tertiary'
                  }`}
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex-1 min-w-0">
                      <div className="font-medium text-am-text-primary mb-1">
                        {comment.user_id}
                      </div>
                      <div className="text-am-text-secondary whitespace-pre-wrap">
                        {comment.comment}
                      </div>
                      <div className="text-am-text-muted mt-1 text-[10px]">
                        {new Date(comment.created_at).toLocaleString()}
                      </div>
                    </div>
                    {!comment.resolved && (
                      <button
                        onClick={() => handleResolve(comment.id)}
                        className="flex-shrink-0 p-1 text-green-400 hover:bg-green-500/20 rounded transition-colors"
                        title="Mark as resolved"
                      >
                        <Check className="w-3 h-3" />
                      </button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* New Comment Input */}
          <div className="flex gap-2">
            <input
              type="text"
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleAddComment()}
              placeholder="Add a comment..."
              className="flex-1 px-3 py-2 text-xs bg-am-secondary border border-am-border rounded-lg text-am-text-primary placeholder-am-text-muted focus:outline-none focus:border-am-accent"
            />
            <button
              onClick={handleAddComment}
              disabled={!newComment.trim() || isSubmitting}
              className="px-3 py-2 bg-am-accent text-white text-xs rounded-lg hover:bg-am-accent-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              <Send className="w-3 h-3" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

// =============================================================================
// Protocol Artifact (Research Phase)
// =============================================================================

interface ProtocolProps {
  content: ProtocolContent;
}

export const ProtocolArtifact: React.FC<ProtocolProps> = ({ content }) => {
  const {
    protein_name,
    ped_id,
    n_conformations,
    binding_site_residues,
    ligands,
    visuals,
    validation_status,
    confidence_score,
    figure_urls,
    literature_results
  } = content;

  const statusColor = {
    pending: 'bg-yellow-500/20 text-yellow-400',
    validated: 'bg-green-500/20 text-green-400',
    failed: 'bg-red-500/20 text-red-400'
  }[validation_status];

  return (
    <div className="bg-slate-900 rounded-xl border border-slate-800 overflow-hidden">
      {/* Header */}
      <div className="bg-slate-800/50 px-4 py-3 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Dna className="w-4 h-4 text-purple-400" />
          <h3 className="text-sm font-semibold text-slate-200">Protocol: {protein_name}</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className={`text-[10px] px-2 py-0.5 rounded ${statusColor}`}>
            {validation_status}
          </span>
          <span className="text-xs text-slate-400">Score: {confidence_score.toFixed(1)}</span>
        </div>
      </div>

      <div className="p-4 space-y-4">
        {/* Target Info */}
        <div className="grid grid-cols-3 gap-3">
          <div className="bg-slate-800/50 rounded-lg p-3 text-center">
            <div className="text-lg font-bold text-purple-400">{ped_id}</div>
            <div className="text-[10px] text-slate-500 uppercase">PED ID</div>
          </div>
          <div className="bg-slate-800/50 rounded-lg p-3 text-center">
            <div className="text-lg font-bold text-slate-300">{n_conformations}</div>
            <div className="text-[10px] text-slate-500 uppercase">Conformations</div>
          </div>
          <div className="bg-slate-800/50 rounded-lg p-3 text-center">
            <div className="text-lg font-bold text-cyan-400">{binding_site_residues?.length || 0}</div>
            <div className="text-[10px] text-slate-500 uppercase">Binding Site</div>
          </div>
        </div>

        {/* Binding Site Residues */}
        {binding_site_residues && binding_site_residues.length > 0 && (
          <div>
            <div className="text-xs text-slate-500 mb-2">Binding Site Residues</div>
            <div className="flex flex-wrap gap-1">
              {binding_site_residues.map((res, idx) => (
                <span key={idx} className="px-2 py-0.5 bg-cyan-900/30 rounded text-xs text-cyan-300 font-mono">
                  Y{res}
                </span>
              ))}
            </div>
          </div>
        )}

        {/* Ligands with Images */}
        {ligands && ligands.length > 0 && (
          <div>
            <div className="text-xs text-slate-500 mb-2">Ligands ({ligands.length})</div>
            <div className="grid grid-cols-2 gap-3">
              {ligands.map((lig, idx) => (
                <div key={idx} className="bg-slate-800/30 rounded-lg p-3 flex gap-3">
                  {/* Ligand 2D Image */}
                  {lig.image_base64 && (
                    <div className="w-16 h-16 flex-shrink-0 bg-white rounded overflow-hidden">
                      <img
                        src={`data:image/png;base64,${lig.image_base64}`}
                        alt={lig.name}
                        className="w-full h-full object-contain"
                      />
                    </div>
                  )}
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-medium text-slate-200">{lig.name}</div>
                    <div className="text-[10px] text-slate-500 font-mono truncate mt-1">
                      {lig.smiles?.slice(0, 30)}...
                    </div>
                    {lig.chembl_id && (
                      <div className="text-[10px] text-purple-400 mt-1">{lig.chembl_id}</div>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Visual Links */}
        {visuals && (
          <div>
            <div className="text-xs text-slate-500 mb-2">Visual Resources</div>
            <div className="flex flex-wrap gap-2">
              {visuals.ped_viewer_url && (
                <a
                  href={visuals.ped_viewer_url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-xs px-3 py-1.5 bg-purple-900/30 text-purple-300 rounded-lg hover:bg-purple-900/50 transition-colors"
                >
                  View on PED
                </a>
              )}
            </div>
          </div>
        )}

        {/* Figure URLs */}
        {figure_urls && figure_urls.length > 0 && (
          <div>
            <div className="text-xs text-slate-500 mb-2">Validation Figures</div>
            <div className="grid grid-cols-3 gap-2">
              {figure_urls.slice(0, 3).map((url, idx) => (
                <a
                  key={idx}
                  href={url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="aspect-video bg-slate-800 rounded overflow-hidden hover:ring-2 ring-purple-500 transition-all"
                >
                  <img src={url} alt={`Figure ${idx + 1}`} className="w-full h-full object-cover" />
                </a>
              ))}
            </div>
          </div>
        )}

        {/* Literature */}
        {literature_results && literature_results.length > 0 && (
          <div>
            <div className="text-xs text-slate-500 mb-2">Literature Evidence</div>
            <div className="space-y-1">
              {literature_results.slice(0, 3).map((paper, idx) => (
                <div key={idx} className="text-xs text-slate-400 flex items-center gap-2">
                  <BookOpen className="w-3 h-3 text-slate-500" />
                  <span className="truncate">{paper.title}</span>
                  {paper.pmcid && (
                    <span className="text-purple-400 font-mono flex-shrink-0">{paper.pmcid}</span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// =============================================================================
// Experiment Matrix Artifact (Engineering Phase)
// =============================================================================

interface ExperimentMatrixProps {
  content: ExperimentMatrixContent;
}

export const ExperimentMatrixArtifact: React.FC<ExperimentMatrixProps> = ({ content }) => {
  const { ligands, n_clusters, representative_frames } = content;

  const completed = ligands.filter(l => l.status === 'completed').length;
  const running = ligands.filter(l => l.status === 'running').length;

  return (
    <div className="bg-slate-900 rounded-xl border border-slate-800 overflow-hidden">
      {/* Header */}
      <div className="bg-slate-800/50 px-4 py-3 border-b border-slate-800 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Server className="w-4 h-4 text-orange-400" />
          <h3 className="text-sm font-semibold text-slate-200">Experiment Matrix</h3>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-slate-400">{completed}/{ligands.length} complete</span>
          {running > 0 && (
            <span className="flex items-center gap-1 text-xs text-orange-400">
              <Loader2 className="w-3 h-3 animate-spin" />
              {running} running
            </span>
          )}
        </div>
      </div>

      <div className="p-4 space-y-4">
        {/* Cluster Info */}
        <div className="grid grid-cols-2 gap-3">
          <div className="bg-slate-800/50 rounded-lg p-3 text-center">
            <div className="text-lg font-bold text-orange-400">{n_clusters}</div>
            <div className="text-[10px] text-slate-500 uppercase">Clusters</div>
          </div>
          <div className="bg-slate-800/50 rounded-lg p-3 text-center">
            <div className="text-lg font-bold text-slate-300">{representative_frames?.length || 0}</div>
            <div className="text-[10px] text-slate-500 uppercase">Representatives</div>
          </div>
        </div>

        {/* Ligand Results Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="text-slate-500 border-b border-slate-800">
                <th className="text-left py-2 px-2">Ligand</th>
                <th className="text-center py-2 px-2">Status</th>
                <th className="text-right py-2 px-2">Energy</th>
                <th className="text-center py-2 px-2">Cluster</th>
              </tr>
            </thead>
            <tbody>
              {ligands.map((lig, idx) => (
                <tr key={idx} className="border-b border-slate-800/50">
                  <td className="py-2 px-2 text-slate-300">{lig.name}</td>
                  <td className="py-2 px-2 text-center">
                    {lig.status === 'completed' && <CheckCircle2 className="w-4 h-4 text-green-400 mx-auto" />}
                    {lig.status === 'running' && <Loader2 className="w-4 h-4 text-orange-400 mx-auto animate-spin" />}
                    {lig.status === 'queued' && <Circle className="w-4 h-4 text-slate-500 mx-auto" />}
                    {lig.status === 'failed' && <X className="w-4 h-4 text-red-400 mx-auto" />}
                  </td>
                  <td className="py-2 px-2 text-right font-mono text-green-400">
                    {lig.best_energy ? `${lig.best_energy.toFixed(1)}` : '-'}
                  </td>
                  <td className="py-2 px-2 text-center text-slate-400">
                    {lig.best_cluster !== undefined ? `C${lig.best_cluster + 1}` : '-'}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

