// =============================================================================
// Main Artifact Renderer
// =============================================================================

interface ArtifactRendererProps {
  artifact: Artifact;
  onStructureClick?: (pdbData: string) => void;
  enableFeedback?: boolean;
}

export const ArtifactRenderer: React.FC<ArtifactRendererProps> = ({
  artifact,
  onStructureClick,
  enableFeedback = true,
}) => {
  // Guard against malformed artifacts
  if (!artifact || !artifact.type) {
    console.warn('ArtifactRenderer: Invalid artifact', artifact);
    return null;
  }

  const renderArtifact = () => {
    try {
    switch (artifact.type) {
      case ArtifactType.TASK_LIST:
        return <TaskListArtifact content={artifact.content as TaskListContent} />;

      case ArtifactType.DOCKING_RESULT:
        return <DockingResultArtifact content={artifact.content as DockingResultContent} />;

      case ArtifactType.INTERACTION_MAP:
        return <InteractionMapArtifact content={artifact.content as InteractionMapContent} />;

      case ArtifactType.LITERATURE_RESULT:
        return <LiteratureArtifact content={artifact.content as LiteratureContent} />;

      case ArtifactType.CLUSTER_VISUALIZATION:
        return <ClusterVisualizationArtifact content={artifact.content as ClusterContent} />;

      case ArtifactType.IMPLEMENTATION_PLAN:
        return <MarkdownArtifact content={artifact.content as string} title="Implementation Plan" />;

      case ArtifactType.WALKTHROUGH:
        return <MarkdownArtifact content={artifact.content as string} title="Walkthrough" />;

      case ArtifactType.STRUCTURE_3D:
        // Handler to open interactive HTML viewer in new window
        const openHtmlViewer = () => {
          const htmlContent = artifact.content.html_viewer;
          if (htmlContent) {
            const newWindow = window.open('', '_blank', 'width=900,height=700');
            if (newWindow) {
              newWindow.document.write(htmlContent);
              newWindow.document.close();
            }
          }
        };

        return (
          <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-semibold text-slate-200 flex items-center gap-2">
                <svg className="w-4 h-4 text-green-400" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M12 2L2 7l10 5 10-5-10-5z" />
                  <path d="M2 17l10 5 10-5" />
                  <path d="M2 12l10 5 10-5" />
                </svg>
                3D Structure
              </h3>
              <div className="flex gap-2">
                {/* Interactive py3Dmol viewer (opens in new window) */}
                {artifact.content.html_viewer && (
                  <button
                    onClick={openHtmlViewer}
                    className="text-xs px-3 py-1 bg-cyan-500 hover:bg-cyan-600 text-white rounded transition-colors"
                  >
                    Open Interactive
                  </button>
                )}
                {/* Molstar viewer (inline) */}
                {onStructureClick && artifact.content.pdb_data && (
                  <button
                    onClick={() => onStructureClick(artifact.content.pdb_data)}
                    className="text-xs px-3 py-1 bg-green-500 hover:bg-green-600 text-white rounded transition-colors"
                  >
                    View in Molstar
                  </button>
                )}
              </div>
            </div>
            <div className="grid grid-cols-2 gap-2 text-xs">
              {artifact.content.metadata?.ped_id && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">PED ID:</span>
                  <span className="ml-2 text-slate-300 font-mono">{artifact.content.metadata.ped_id}</span>
                </div>
              )}
              {artifact.content.metadata?.n_conformations && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">Conformations:</span>
                  <span className="ml-2 text-slate-300">{artifact.content.metadata.n_conformations}</span>
                </div>
              )}
              {artifact.content.ligand_name && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">Ligand:</span>
                  <span className="ml-2 text-cyan-300">{artifact.content.ligand_name}</span>
                </div>
              )}
              {artifact.content.n_frames && (
                <div className="bg-slate-800/50 rounded p-2">
                  <span className="text-slate-500">Frames:</span>
                  <span className="ml-2 text-slate-300">{artifact.content.n_frames}</span>
                </div>
              )}
            </div>
          </div>
        );

      case ArtifactType.PROTOCOL:
        return <ProtocolArtifact content={artifact.content as ProtocolContent} />;

      case ArtifactType.EXPERIMENT_MATRIX:
        return <ExperimentMatrixArtifact content={artifact.content as ExperimentMatrixContent} />;

      case ArtifactType.DISCOVERY_REPORT:
        return <DiscoveryReportArtifact content={artifact.content as DiscoveryReportContent} />;

      case ArtifactType.PUBLICATION_FIGURE:
        return <PublicationFigureArtifact content={artifact.content as PublicationFigureContent} />;

      default:
        return (
          <div className="bg-slate-900 rounded-xl p-4 border border-slate-800">
            <pre className="text-xs text-slate-400 overflow-auto">
              {JSON.stringify(artifact.content, null, 2)}
            </pre>
          </div>
        );
    }
    } catch (e) {
      console.error('Error rendering artifact:', artifact.type, e);
      return (
        <div className="bg-red-900/20 rounded-xl p-4 border border-red-800">
          <div className="text-red-400 text-sm">Error rendering artifact</div>
          <div className="text-red-300 text-xs mt-1">{String(e)}</div>
        </div>
      );
    }
  };

  // Wrap with feedback if enabled
  if (enableFeedback) {
    return (
      <ArtifactWithFeedback artifact={artifact} onStructureClick={onStructureClick}>
        {renderArtifact()}
      </ArtifactWithFeedback>
    );
  }

  return renderArtifact();
};

export default ArtifactRenderer;
